package io.github.chronicle.core.server;

import io.github.chronicle.core.areas.*;
import io.github.chronicle.core.menu.CoreMenuModel.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.command.ServerCommandSource;
import net.minecraft.server.network.ServerPlayerEntity;
import java.util.*;

/** Typed world actions use Area operation receipts; they never execute inside flag-only cue handlers. */
final class AreaWorldEvents {
    private AreaWorldEvents(){}
    record Target(AreaChange area,AreaState state){}
    static List<Entry> entries(MinecraftServer server){List<Entry> result=new ArrayList<>();for(AreaChange area:AreaChanges.catalog(server).areas().values())for(AreaState state:AreaState.values())result.add(new Entry("world:"+area.id()+":"+state.name().toLowerCase(Locale.ROOT),area.name()+" → "+state,"Apply a saved Area state after review.","WORLD_ACTION",area.id(),area.revision()));return result;}
    static Target target(MinecraftServer server,String id){if(!id.startsWith("world:"))throw new IllegalArgumentException("Choose an Area world action.");int split=id.lastIndexOf(':');AreaChange area=AreaChanges.catalog(server).areas().get(id.substring(6,split));if(area==null)throw new IllegalStateException("The Area linked to this action is missing.");AreaState state=switch(id.substring(split+1)){case "start"->AreaState.START;case "end"->AreaState.END;default->throw new IllegalArgumentException("Choose Start or End.");};return new Target(area,state);}
    static String review(ServerPlayerEntity player,String id){var server=player.getEntityWorld().getServer();Target t=target(server,id);AreaChanges.currentRegion(server,t.area());t.area().requireSnapshot(t.state());if(RuntimeHolds.reason(server)!=null||WorldAreaOperations.busy(server))throw new IllegalStateException("Finish the current operation first.");return "Apply "+t.state()+" to '"+t.area().name()+"'. Its blocks and container contents will be replaced, discarding the old contents. All non-spectator players must be outside the Region. This creates a new durable Area operation.";}
    static String preview(ServerPlayerEntity player,String id){Target t=target(player.getEntityWorld().getServer(),id);AreaChanges.currentRegion(player.getEntityWorld().getServer(),t.area());t.area().requireSnapshot(t.state());AuthoringRuntime.get(player.getEntityWorld().getServer()).preview(player,AreaChanges.currentRegion(player.getEntityWorld().getServer(),t.area()));return "Private Area outline: "+t.area().name()+" / "+t.state()+". No blocks changed.";}
    static String run(ServerCommandSource source,String id){Target t=target(source.getServer(),id);UUID operation=WorldAreaOperations.apply(source,t.area().id(),t.state(),t.area().revision(),false);return "World action preparing; completion is recorded only after Area operation "+operation+" verifies and saves.";}
    static Detail detail(ServerPlayerEntity player,String id,boolean reviewed){var server=player.getEntityWorld().getServer();Target t=target(server,id);boolean valid=!AreaChanges.stale(server,t.area())&&t.area().snapshot(t.state()).isPresent(),free=RuntimeHolds.reason(server)==null&&!WorldAreaOperations.busy(server),allowed=ChronicleRuntime.service(server).state().phase()==io.github.chronicle.core.campaign.SessionPhase.ACTIVE||AuthoringRuntime.isAuthor(player);List<Control> controls=new ArrayList<>();controls.add(new Control(Action.EVENT_PREVIEW,"Preview area",valid,"Save this state and resolve its Region reference first.",false,""));controls.add(new Control(Action.EVENT_REVIEW,"Review world change",valid&&free&&allowed,"Use active play or Editing, with a current saved state and no pending operation.",false,""));if(reviewed)controls.add(new Control(Action.EVENT_RUN,"Apply reviewed state",true,"",true,""));List<Fact> facts=new ArrayList<>();AreaChanges.operations(server).state().operations().values().stream().filter(o->o.areaId().equals(t.area().id())&&o.requestedState().orElse(null)==t.state()).reduce((a,b)->b).ifPresent(o->facts.add(new Fact("Latest Area operation",o.operationId()+" / "+o.stage())));return new Detail(id,t.area().name()+" → "+t.state(),"Replace this Region with its saved "+t.state()+" state. Preview shows its bounds without changing the world.",facts,controls,null,null,null);}
}
